---level31 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl31_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end		game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		game.pauseLogic()		sound.play(55-2)		if dialog.show("Level31-1", faceZhoumei) ==1 then break end		camera.setFollowRoleMode(false)		camera.gotoPosition(447,776)		if dialog.show("Level31-2", faceBujie) ==1 then break end		if dialog.show("Level31-3", faceBujie) ==1 then break end		camera.gotoRole()		camera.setFollowRoleMode(true)				--set story viewed flag        global.setBool("lvl31_b1")		game.resumeLogic()				game.restartTiming()		game.setUserInputEnabled(true)		role.setIdleActionEnabled(true)		isPlayingDemo = false		isSkip = false	until trueendif isSkip then	camera.gotoRole()	camera.setFollowRoleMode(true)	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()end